.error-boundary { display: flex; align-items: center; justify-content: center; height: 100%; padding: 40px; }.error-boundary-card { text-align: center; border: 1px solid rgb(42, 45, 58); border-radius: 12px; padding: 30px; background: rgb(18, 18, 18); }.error-boundary-card h2 { color: rgb(255, 51, 102); margin-bottom: 10px; }.error-boundary-card p { color: rgb(161, 164, 176); margin-bottom: 16px; }.error-boundary-card button { padding: 10px 20px; background: rgb(0, 255, 102); color: rgb(0, 26, 8); border: medium; border-radius: 8px; font-weight: 700; cursor: pointer; }.chart-wrap { position: relative; width: 100%; flex: 1 1 0%; min-height: 0px; }.chart-wrap .chart-container { position: absolute; inset: 0px; }.chart-overlay { position: absolute; inset: 0px; display: flex; align-items: center; justify-content: center; color: rgb(161, 164, 176); font-size: 13px; background: rgba(18, 18, 18, 0.6); z-index: 5; }.chart-overlay.chart-error { color: rgb(255, 51, 102); }.panel-header-right { display: flex; align-items: center; gap: 8px; }.bias-pill { display: inline-flex; align-items: center; gap: 4px; font-size: 11px; font-weight: 800; padding: 4px 8px; border-radius: 6px; }.bias-pill.bias-long { color: rgb(0, 255, 102); background: rgba(0, 255, 102, 0.08); border: 1px solid rgba(0, 255, 102, 0.267); }.bias-pill.bias-short { color: rgb(255, 51, 102); background: rgba(255, 51, 102, 0.08); border: 1px solid rgba(255, 51, 102, 0.267); }.tf-badge { display: inline-flex; align-items: center; gap: 4px; font-size: 10px; color: rgb(161, 164, 176); background: rgb(26, 26, 26); padding: 3px 6px; border-radius: 5px; }.all-aligned { text-align: center; font-weight: 800; font-size: 12px; letter-spacing: 1px; padding: 8px; border-radius: 8px; margin: 0px 16px 12px; animation: 1.5s infinite pulseGlow; }.all-aligned.aligned-long { color: rgb(0, 255, 102); background: rgba(0, 255, 102, 0.094); border: 1px solid rgb(0, 255, 102); }.all-aligned.aligned-short { color: rgb(255, 51, 102); background: rgba(255, 51, 102, 0.094); border: 1px solid rgb(255, 51, 102); }@keyframes pulseGlow { 
  0%,100% { opacity: 1; }
  50% { opacity: 0.55; }
}.rule-item.rule-long { border-left: 2px solid rgb(0, 255, 102); }.rule-item.rule-short { border-left: 2px solid rgb(255, 51, 102); }.rules-loading, .no-signal-hint, .rules-loading { padding: 14px 16px; font-size: 12px; }.indicator-strip { display: flex; gap: 16px; padding: 8px 16px; font-size: 11px; color: rgb(161, 164, 176); border-top: 1px solid rgb(30, 32, 40); }.indicator-strip b { color: rgb(255, 255, 255); margin-left: 4px; }.coin-indicator-long { color: rgb(0, 255, 102) !important; }.coin-indicator-short { color: rgb(255, 51, 102) !important; }.coin-bias-count { font-size: 10px; color: rgb(92, 96, 112); margin-left: 4px; }.auto-toggle { display: flex; align-items: center; justify-content: center; background: none; border: medium; color: rgb(92, 96, 112); cursor: pointer; padding: 3px; border-radius: 4px; transition: color 0.15s; }.auto-toggle:hover { color: rgb(255, 215, 0); background: rgba(255, 255, 255, 0.03); }.auto-toggle.auto-on { color: rgb(255, 215, 0); }.global-stats { display: flex; justify-content: space-around; padding: 12px; border: 1px solid rgb(42, 45, 58); border-radius: 10px; }.global-stat { display: flex; flex-direction: column; align-items: center; gap: 2px; }.global-stat span:first-child { font-size: 18px; font-weight: 800; }.global-stat .text-muted { font-size: 10px; }.trade-row { display: flex; align-items: center; gap: 8px; padding: 7px 0px; border-bottom: 1px solid rgb(30, 32, 40); }@media (max-width: 900px) {
  .app-layout { grid-template-columns: 1fr; grid-auto-rows: auto; height: auto; overflow-y: auto; }
  .coin-sidebar { max-height: 240px; overflow-y: auto; }
  .main-content { min-height: 70vh; }
  .right-panel { max-height: none; }
  .main-chart .chart-container { min-height: 300px; }
}
